<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$db->prepare('INSERT INTO expenses(category,description,amount) VALUES(?,?,?)')->execute([trim($_POST['category']),trim($_POST['description']??''),max(0,(float)$_POST['amount'])]);header('Location: expenses.php?saved=1');exit;}catch(Throwable $e){$error=$e->getMessage();}} $rows=$db->query('SELECT * FROM expenses ORDER BY id DESC LIMIT 200')->fetchAll(); $today=(float)$db->query('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE DATE(created_at)=CURDATE()')->fetchColumn(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expenses</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">CASH CONTROL</div><h1>Expenses</h1><p>Record operating expenses and monitor daily spending.</p></div></div><section class="panel"><h2>Today's Expenses: Rs. <?=money($today)?></h2><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post" class="grid"><label>Category<input name="category" required placeholder="Rent, electricity, salary..."></label><label>Description<input name="description"></label><label>Amount<input name="amount" type="number" min="0" step="0.01" required></label><button class="btn">Record Expense</button></form></section><section class="panel"><table><tr><th>Date</th><th>Category</th><th>Description</th><th>Amount</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td>Rs. <?=money($r['amount'])?></td></tr><?php endforeach;?></table></section></main></body></html>